"""FORGE PASS — crisp branching production master.
Paste the ENTIRE script into Blender's Text Editor and click Run Script.
No add-ons, pip installs, external geometry or textures are required.
Creates three new scenes; preserves existing scenes. Saves a new .blend file.
"""
import bpy
import math
import json
import sys
from pathlib import Path
from datetime import datetime
from mathutils import Vector

# SETTINGS — change these only if you want different export settings.
RESOLUTION = 2048
FPS = 20
MOTION_SECONDS = 24
VOLUMETRIC_SECONDS = 12
RENDER_SAMPLES = 64
SAVE_PROJECT = True
OUTPUT_FOLDER = str(Path.home() / 'Documents' / 'ForgePass_Blender')
# Embedded approved source geometry is assigned above this body by the distributor.


def linear(c):
    c=c/255
    return c/12.92 if c<=.04045 else ((c+.055)/1.055)**2.4


MATERIALS={}
def material(rgb):
    rgb=tuple(rgb)
    if rgb not in MATERIALS:
        m=bpy.data.materials.new('FP RGB '+str(rgb));m.use_nodes=True
        col=tuple(linear(c) for c in rgb)
        m.diffuse_color=(*col,1)
        nodes=m.node_tree.nodes;nodes.clear()
        e=nodes.new('ShaderNodeEmission');e.inputs['Color'].default_value=(*col,1)
        e.inputs['Strength'].default_value=1
        out=nodes.new('ShaderNodeOutputMaterial');m.node_tree.links.new(e.outputs[0],out.inputs['Surface'])
        MATERIALS[rgb]=m
    return MATERIALS[rgb]


class Batch:
    def __init__(self):
        self.verts=[];self.faces=[];self.colors=[]
    def poly(self,pts,color,z):
        n=len(self.verts)
        self.verts.extend((p[0]/100,-p[1]/100,z) for p in pts)
        self.faces.append(tuple(range(n,n+len(pts))));self.colors.append(tuple(color))
    def disc(self,p,r,color,z,segments=48):
        self.poly([(p[0]+r*math.cos(i*math.tau/segments),p[1]+r*math.sin(i*math.tau/segments)) for i in range(segments)],color,z)
    def stroke(self,pts,width,color,z,end_scale=1,offset=(0,0)):
        pts=[Vector(p) for p in pts]
        dirs=[(b-a).normalized() for a,b in zip(pts[:-1],pts[1:])]
        ns=[Vector((-d.y,d.x)) for d in dirs]
        left=[];right=[]
        for i,p in enumerate(pts):
            if i==0:n=ns[0].copy()
            elif i==len(pts)-1:n=ns[-1].copy()
            else:
                n=ns[i-1]+ns[i]
                n=n.normalized() if n.length>1e-8 else ns[i].copy()
                n/=max(.6,n.dot(ns[i]))
            w=width*(1+(end_scale-1)*i/(len(pts)-1))
            left.append(p+n*w/2+Vector(offset));right.append(p-n*w/2+Vector(offset))
        for i in range(len(pts)-1):self.poly([left[i],right[i],right[i+1],left[i+1]],color,z)
        return left,right
    def arc(self,r,w,color,z,start=0,span=360,offset=(0,0)):
        count=max(8,math.ceil(span*1.5))
        pts=[(r*math.cos(math.radians(start+span*i/count)),r*math.sin(math.radians(start+span*i/count))) for i in range(count+1)]
        self.stroke(pts,w,color,z,offset=offset)
    def finish(self,name,scene,parent=None):
        mesh=bpy.data.meshes.new(name);mesh.from_pydata(self.verts,[],self.faces);mesh.update()
        slots={}
        for color in self.colors:
            if color not in slots:
                slots[color]=len(slots);mesh.materials.append(material(color))
        for face,col in zip(mesh.polygons,self.colors):face.material_index=slots[col]
        ob=bpy.data.objects.new(name,mesh);scene.collection.objects.link(ob);ob.parent=parent
        return ob


def empty(name,scene):
    ob=bpy.data.objects.new(name,None);scene.collection.objects.link(ob);return ob


def rail(b,path,width,z,rear=False):
    primary=width>2.5;secondary=width>=1.7
    if rear:
        w=3.6 if primary else (2 if secondary else 1.2)
        b.stroke(path,w+1.5,(6,86,159),z)
        b.stroke(path,w,(13,137,218),z+.001)
        if primary:b.stroke(path,.7,(63,174,233),z+.002)
        return
    w=15.6 if primary else (6.4 if secondary else 2.9)
    if primary and len(path)==2:w=12.5
    taper=.58 if primary else .7
    b.stroke(path,w,(1,26,49),z,end_scale=taper,offset=(3,5.5))
    b.stroke(path,w,(2,63,92),z+.001,end_scale=taper)
    face=(8,156,194) if primary else ((6,149,192) if secondary else (13,169,207))
    left,right=b.stroke(path,w*.72,face,z+.002,end_scale=taper)
    for i,(a,c) in enumerate(zip(path[:-1],path[1:])):
        d=(Vector(c)-Vector(a)).normalized();n=Vector((-d.y,d.x))
        edge=left if n.dot(Vector((-.707,-.707)))>0 else right
        b.stroke([edge[i],edge[i+1]],1.55 if primary else .85,(126,233,247) if primary else (55,210,232),z+.003)
    if primary:
        b.stroke(path,1.5,(10,105,143),z+.004)
        for p in path[1:-1]:
            for k,(r,col) in enumerate([(4.1,(3,57,84)),(2.3,(47,196,223)),(1,(167,244,253))]):b.disc(p,r,col,z+.005+k*.001)


def branches(scene,layer):
    root=empty(layer+' branch assembly',scene)
    arms=[]
    for arm in range(len(GEOMETRY['angles'])):
        ob=empty(layer+f' arm {arm}',scene);ob.parent=root;arms.append(ob)
        b=Batch()
        paths=sorted([p for p in GEOMETRY['paths'] if p[2]==arm],key=lambda p:-p[1])
        for i,(path,width,_) in enumerate(paths):
            # A hidden continuation keeps the root joined to the fixed hub throughout bloom.
            if width>2.5 and math.hypot(*path[0])<82:
                rail(b,[[0,0],path[0]],width,-.02,layer=='rear')
            rail(b,path,width,i*.012,layer=='rear')
        for p,a in GEOMETRY['tips']:
            if a!=arm:continue
            if layer=='rear':b.disc(p,2.8,(22,139,205),.3)
            else:
                b.disc((p[0]+1.8,p[1]+2.7),4.5,(2,47,69),.30)
                for k,(r,col) in enumerate([(4,(3,110,148)),(2.4,(82,220,237)),(1,(196,248,252))]):b.disc(p,r,col,.301+k*.001)
        b.finish(layer+f' precision rails {arm}',scene,ob)
    return root,arms


def halo(scene,layer):
    parent=empty(layer+' halo',scene);b=Batch();r=500
    for i in range(10):
        a=3+i*36
        if layer=='rear':
            b.arc(r,2.6,(12,108,187),0,a,28);b.arc(r-.8,.7,(30,158,220),.001,a,28)
        else:
            light=(1+math.cos(math.radians(a+14-225)))*.5
            b.arc(r+1,12.5,(1,24,45),0,a,28,(3,5.5))
            b.arc(r,11,(2,68,101),.001,a,28)
            b.arc(r-1.8,7,(5,int(143+31*light),int(189+22*light)),.002,a,28)
            b.arc(r-2,1.4,(int(70+60*light),int(209+26*light),int(233+14*light)),.003,a,28)
            b.arc(r-8,1,(4,95,143),.004,a,28)
    b.finish(layer+' segmented halo faces',scene,parent);return parent


def hub(scene):
    b=Batch();b.disc((0,0),82,(2,22,39),1.4,192)
    for r in range(80,0,-1):
        t=1-r/80;b.disc((-1.7,-2.4),r,(int(5+8*t),int(37+15*t),int(58+17*t)),1.401+(80-r)*.0001,192)
    for i,(r,w,col) in enumerate([(79,3,(10,85,114)),(75,1,(124,226,242)),(68,7,(3,24,42)),(62,3,(3,126,172)),(52,8,(4,77,109)),(47,1.5,(75,220,239)),(37,6,(2,26,44)),(30,5,(17,172,204))]):b.arc(r-w/2,w,col,1.42+i*.001)
    for deg in range(0,360,72):
        p=(68*math.cos(math.radians(deg-18)),68*math.sin(math.radians(deg-18)))
        b.disc(p,3.8,(3,23,37),1.44);b.disc(p,1.6,(61,171,194),1.441)
    verts=[(24*math.cos(math.radians(30+i*60)),24*math.sin(math.radians(30+i*60))) for i in range(6)]
    colors=[(76,216,231),(10,141,177),(6,107,150),(26,170,199),(166,243,250),(111,231,243)]
    for i,col in enumerate(colors):b.poly([(0,0),verts[i],verts[(i+1)%6]],col,1.45)
    b.disc((-3,-4),5,(207,253,255),1.451)
    return b.finish('Fixed detailed hub and faceted core',scene)


def background(scene):
    b=Batch();b.poly([(-1000,-1000),(1000,-1000),(1000,1000),(-1000,1000)],(5,9,15),-.5)
    # Fine concentric steps reproduce the reference's restrained radial background.
    for i,r in enumerate(range(640,0,-4)):
        t=1-r/640;b.disc((0,0),r,(round(5+3*t),round(9+6*t),round(15+9*t)),-.49+i*.00001,192)
    b.arc(548,.65,(5,36,53),-.2)
    for a in range(0,360,12):
        rad=math.radians(a);b.stroke([(545*math.cos(rad),545*math.sin(rad)),(550*math.cos(rad),550*math.sin(rad))],1,(10,58,78),-.19)
    b.finish('Graphite background and precision ticks',scene)


def set_bloom(arms,frame,count,layer):
    opening=.5+.5*math.sin(math.tau*(frame-1)/count)
    for arm,ob in enumerate(arms):
        front=layer=='front';hinge=(-1 if arm%2==0 else 1)*(4 if front else -1)*opening
        angle=math.radians(GEOMETRY['angles'][arm]+hinge);radial=(.35 if front else .07)*opening
        scale=.78+(.19 if front else .07)*opening
        ob.location=(radial*math.cos(angle),-radial*math.sin(angle),.55+.15*opening if front else 0)
        ob.scale=(scale,scale,1);ob.rotation_euler.z=-math.radians(hinge)
    return opening


def linear_keys(ob):
    if not ob.animation_data or not ob.animation_data.action:return
    action=ob.animation_data.action
    if hasattr(action,'fcurves'):curves=action.fcurves
    else:
        curves=[]
        for layer in action.layers:
            for strip in layer.strips:
                bag=strip.channelbag(ob.animation_data.action_slot)
                if bag:curves.extend(bag.fcurves)
    for c in curves:
        for point in c.keyframe_points:point.interpolation='LINEAR'


def build_scene(tier):
    scene=bpy.data.scenes.new('FORGE '+tier);bpy.context.window.scene=scene
    engines=scene.render.bl_rna.properties['engine'].enum_items.keys()
    scene.render.engine='BLENDER_EEVEE_NEXT' if 'BLENDER_EEVEE_NEXT' in engines else 'CYCLES'
    scene.cycles.use_denoising=False;scene.cycles.samples=RENDER_SAMPLES
    if hasattr(scene,'eevee') and hasattr(scene.eevee,'taa_render_samples'):scene.eevee.taa_render_samples=RENDER_SAMPLES
    scene.render.resolution_x=scene.render.resolution_y=RESOLUTION;scene.render.resolution_percentage=100
    scene.render.image_settings.file_format='PNG';scene.render.image_settings.color_mode='RGB';scene.render.fps=FPS
    scene.render.filepath='//frames/'+tier+'_'
    scene.view_settings.view_transform='Standard';scene.view_settings.look='None';scene.view_settings.exposure=0;scene.view_settings.gamma=1
    world=bpy.data.worlds.new('FORGE dark world');world.use_nodes=True;world.node_tree.nodes['Background'].inputs[1].default_value=0;scene.world=world
    background(scene);fixed_hub=hub(scene)
    front,arms=branches(scene,'front');outer=halo(scene,'front');outer.location.z=.9
    scene.frame_start=1;scene.frame_end=1
    if tier=='Volumetric':
        rear,rear_arms=branches(scene,'rear');inner=halo(scene,'rear');inner.location.z=.35
        count=FPS*VOLUMETRIC_SECONDS;scene.frame_end=count
        for frame in range(1,count+2):
            opening=set_bloom(arms,frame,count,'front');set_bloom(rear_arms,frame,count,'rear')
            outer.scale=((405+108*opening)/500,)*2+(1,);inner.scale=((405+43*opening)/500,)*2+(1,)
            for ob in arms+rear_arms:
                for prop in ('location','scale','rotation_euler'):ob.keyframe_insert(prop,frame=frame)
            for ob in (outer,inner):ob.keyframe_insert('scale',frame=frame)
        for label,frame in [('OPEN',count//4+1),('CLOSED',count*3//4+1)]:scene.timeline_markers.new(label,frame=frame)
    else:
        set_bloom(arms,61,240,'front');outer.scale=(513/500,513/500,1)
        if tier=='Motion':
            count=FPS*MOTION_SECONDS;scene.frame_end=count
            for ob,direction in [(front,-1),(outer,1)]:
                for frame,angle in [(1,0),(count+1,direction*math.tau)]:
                    ob.rotation_euler.z=angle;ob.keyframe_insert('rotation_euler',index=2,frame=frame)
            scene.timeline_markers.new('Quarter turn',frame=count//4+1)
    for ob in scene.objects:linear_keys(ob)
    camera_data=bpy.data.cameras.new('FORGE orthographic camera');camera_data.type='ORTHO';camera_data.ortho_scale=1280/1.08/100
    camera=bpy.data.objects.new('FORGE orthographic camera',camera_data);scene.collection.objects.link(camera);camera.location=(0,0,15);scene.camera=camera
    scene['design']='Crisp branching master — explicit coloured rail faces and highlights, detailed terminals and hub.'
    scene['source_seed']=GEOMETRY['seed'];scene['tier']=tier
    scene['render_method']='Layered editable meshes with colour-controlled emission materials; not physically based lighting.'
    # Every object transform must close at the excluded duplicate endpoint.
    scene.frame_set(1);dg=bpy.context.evaluated_depsgraph_get()
    first={ob.name:ob.evaluated_get(dg).matrix_world.copy() for ob in scene.objects}
    scene.frame_set(scene.frame_end+1)
    dg=bpy.context.evaluated_depsgraph_get()
    error=max(abs(ob.evaluated_get(dg).matrix_world[i][j]-first[ob.name][i][j]) for ob in scene.objects for i in range(4) for j in range(4))
    assert error<1e-5,(tier,error)
    scene.frame_set(61 if tier=='Volumetric' else 1)
    return scene,{'tier':tier,'loop_transform_error':error,'objects':len(scene.objects),'frames':scene.frame_end,'fps':FPS}


def main():
    global RESOLUTION,OUTPUT_FOLDER
    # CLI overrides are optional; normal paste-and-run uses the settings above.
    args=sys.argv[sys.argv.index('--')+1:] if '--' in sys.argv else []
    if '--output' in args:OUTPUT_FOLDER=args[args.index('--output')+1]
    if '--size' in args:RESOLUTION=int(args[args.index('--size')+1])
    scenes=[];reports=[]
    for tier in ('Preview','Motion','Volumetric'):
        scene,report=build_scene(tier);scenes.append(scene);reports.append(report)
    bpy.context.window.scene=scenes[2]
    for screen in bpy.data.screens:
        for area in screen.areas:
            if area.type=='VIEW_3D':
                area.spaces.active.region_3d.view_perspective='CAMERA'
                area.spaces.active.overlay.show_overlays=False
                area.spaces.active.shading.type='MATERIAL'
    out=Path(OUTPUT_FOLDER).expanduser();out.mkdir(parents=True,exist_ok=True)
    if SAVE_PROJECT:
        target=out/'ForgePass_Crisp_Branches_Master.blend'
        if target.exists():target=out/('ForgePass_Crisp_Branches_Master_'+datetime.now().strftime('%Y%m%d_%H%M%S')+'.blend')
        bpy.ops.wm.save_as_mainfile(filepath=str(target))
    (out/'Build_Report.json').write_text(json.dumps(reports,indent=2)+'\n')
    if '--render' in args:
        for scene,frames in [(scenes[0],[1]),(scenes[1],[121]),(scenes[2],[61,181])]:
            bpy.context.window.scene=scene
            for frame in frames:
                scene.frame_set(frame);scene.render.filepath=str(out/(scene['tier']+f'_{frame:03d}.png'));bpy.ops.render.render(write_still=True)
    bpy.context.window.scene=scenes[2]
    print('FORGE MASTER READY — scenes: '+', '.join(s.name for s in scenes),flush=True)


if __name__=='__main__':main()
